/* the reference left toasts stock (Sonner defaults), so these are built to its
   floating-card craft instead.
   A white float on the soft two-layer lift, a hairline and a specular top
   edge; the tone carried by a small gradient tile with the brand gesture's
   glow; a timer rule for toasts that leave on their own; and a deck that
   fans out under the pointer. Every colour is a token, so the flat preset
   turns the tile flat, the glow off and the corners square. */

.region {
  position: fixed;
  right: 20px;
  bottom: 20px;
  z-index: var(--z-toast);
  width: min(380px, calc(100vw - 32px));
  pointer-events: none;
}

/* Rendered in place for the styleguide: same stack, in the page flow. */
.preview {
  position: relative;
  width: 380px;
  max-width: 100%;
}

/* Pinned open, the preview lays its toasts out in normal flow: same
   surfaces, no measuring, no motion, so it sizes itself the moment it
   renders (thumbnails measure it to fit). */
.preview .expanded {
  display: flex;
  flex-direction: column;
  gap: 10px;
  height: auto !important;
  transition: none;
}

.preview .expanded .toast {
  position: relative;
  height: auto;
  transform: none;
  transition: none;
  animation: none;
}

/* The stack's box. Its height is set inline (front toast plus the peeking
   edges, or every toast when fanned out) so the hover target matches what
   is drawn and the gaps between fanned toasts do not collapse it. */
.list {
  position: relative;
  margin: 0;
  padding: 0;
  list-style: none;
  pointer-events: auto;
  transition: height 380ms var(--ease-out);
}

/* ── The toast ───────────────────────────────────────────────────────────
   Collapsed, a toast behind the front one is clamped to the front's height,
   scaled back from its top edge and raised by 9px per step, so exactly 9px
   of each shows above the front: a deck, not a pile. Fanned out, each sits
   at its offset (the heights of the newer toasts plus gaps). Motion is
   transform only; the entrance uses `translate`, a separate property, so it
   composes with the stack transform instead of fighting it. */
.toast {
  position: absolute;
  right: 0;
  bottom: 0;
  left: 0;
  z-index: calc(20 - var(--index));
  /* Always an explicit length (measured), so clamping and unclamping
     animate instead of jumping between a px value and auto. */
  height: var(--own-height);
  overflow: hidden;
  border-radius: var(--toast-radius, var(--r-lg));
  /* Frosted glass, not flat white: translucent white
     with a strong blur, a faint tone tint washed in from the icon side, and
     depth from shadows above and below instead of an outline. */
  /* The colour is the toast's own tone as a full-surface gradient (green for
     success…), over glass opaque enough that the page gradient doesn't show
     through as the dominant colour. */
  background:
    linear-gradient(135deg, rgba(var(--toast-rgb), 0.13) 0%, rgba(var(--toast-rgb), 0.04) 100%),
    var(--toast-surface, rgba(var(--rgb-white), 0.82));
  -webkit-backdrop-filter: var(--toast-blur, blur(28px) saturate(180%));
  backdrop-filter: var(--toast-blur, blur(28px) saturate(180%));
  box-shadow: var(--toast-shadow);
  transform-origin: top center;
  transform: translateY(calc(var(--index) * -9px)) scale(calc(1 - var(--index) * 0.05));
  transition:
    transform 380ms var(--ease-out),
    height 380ms var(--ease-out),
    opacity 200ms var(--ease),
    box-shadow var(--dur) var(--ease);
  animation: toast-in 420ms var(--ease-out) both;
}

.expanded .toast {
  transform: translateY(calc(var(--offset) * -1));
}

.toast {
  --toast-shadow:
    0 -8px 20px -10px rgba(var(--rgb-brand-deep), 0.2),
    0 20px 44px -14px rgba(var(--rgb-brand-deep), 0.36),
    0 4px 10px -3px rgba(var(--rgb-contact), 0.1),
    inset 0 1px 0 rgba(var(--rgb-white), 0.9),
    inset 0 -1px 0 rgba(var(--rgb-brand-deep), 0.06);
}

/* Tone colour for the surface gradient. Default (info, loading) is accent. */
.toast {
  --toast-rgb: var(--toast-rgb-info, 110, 84, 153);
}

.success {
  --toast-rgb: var(--toast-rgb-success, 52, 168, 112);
}

.error {
  --toast-rgb: var(--toast-rgb-error, 237, 93, 87);
}

.clamped {
  height: var(--front-height);
}

/* The toasts behind show only their edge: content fades out so two layers
   of text never overlap, and comes back as the stack fans out. */
.behind .body,
.behind .timer {
  opacity: 0;
}

.hidden {
  opacity: 0;
  pointer-events: none;
}

.leaving {
  pointer-events: none;
  animation: toast-out 220ms var(--ease) forwards;
}

.body {
  display: flex;
  align-items: flex-start;
  gap: 12px;
  padding: calc(14px * var(--density)) calc(12px * var(--density)) calc(14px * var(--density)) calc(14px * var(--density));
  transition: opacity 200ms var(--ease);
}

/* ── Tone tile: the primary gesture in miniature ─────────────────────────
   Gradient fill, tone-coloured glow, dark specular edge, white glyph.
   Radius 8 inside a 12px toast: one rung down the ladder. */
.icon {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  width: 34px;
  height: 34px;
  border-radius: var(--toast-icon-radius, var(--r-sm));
  /* Soft tile:
     a light wash of the tone with the icon drawn in the tone's ink. */
  color: var(--ink-brand);
  background: rgba(var(--toast-rgb), 0.16);
  box-shadow: inset 0 1px 0 rgba(var(--rgb-white), 0.7), inset 0 0 0 1px rgba(var(--toast-rgb), 0.18);
}

.success .icon {
  color: var(--success-ink);
}

.error .icon {
  color: var(--danger-ink);
}

/* info and loading keep the brand gesture from .icon. */

.content {
  display: flex;
  flex: 1;
  flex-direction: column;
  align-items: flex-start;
  gap: 3px;
  min-width: 0;
  padding-top: 1px;
}

.title {
  font-size: var(--text-body);
  font-weight: 700;
  line-height: 1.35;
  letter-spacing: -0.005em;
  color: var(--ink-heading);
  overflow-wrap: anywhere;
}

.description {
  font-size: var(--text-small);
  line-height: 1.45;
  color: var(--ink-secondary);
  overflow-wrap: anywhere;
}

/* Action: a compact washed button with a brand edge, so it reads as a
   control and not as a link in the copy. Flat keeps its tracked caps. */
.action {
  display: inline-flex;
  align-items: center;
  height: 28px;
  margin-top: 8px;
  padding: 0 10px;
  border: 0;
  border-radius: var(--r-xs);
  background: var(--wash-subtle);
  box-shadow: inset 0 0 0 1px var(--line-brand);
  font-family: var(--font-body);
  font-size: var(--button-size-sm, 12.5px);
  font-weight: 700;
  letter-spacing: var(--button-tracking, 0);
  text-transform: var(--button-case, none);
  color: var(--ink-brand);
  cursor: pointer;
  transition:
    background-color var(--dur) var(--ease),
    box-shadow var(--dur) var(--ease);
}

.action:hover {
  background: var(--wash-active);
  box-shadow: inset 0 0 0 1px var(--line-brand-strong);
}

.action:active {
  background: var(--wash-strong);
}

.close {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  width: 26px;
  height: 26px;
  margin: -2px -2px 0 0;
  border: 0;
  border-radius: var(--r-xs);
  background: transparent;
  color: var(--ink-muted);
  cursor: pointer;
  transition:
    background-color var(--dur) var(--ease),
    color var(--dur) var(--ease);
}

.close:hover {
  background: var(--wash-subtle);
  color: var(--ink-brand);
}

.close:active {
  background: var(--wash-active);
}

.action:focus-visible,
.close:focus-visible {
  outline: none;
  box-shadow: var(--focus-ring);
}

/* ── Timer: 2px rule along the bottom edge, draining left to right ───────
   Only on toasts that leave on their own. Paused with the timer (hover or
   focus anywhere in the stack), so what it shows is what is left. */
.timer {
  position: absolute;
  right: 0;
  bottom: 0;
  left: 0;
  height: 2px;
  background: var(--brand-gradient);
  opacity: 0.55;
  transform-origin: left center;
  animation: toast-timer var(--toast-duration) linear forwards;
  transition: opacity 200ms var(--ease);
}

.success .timer {
  background: var(--success-gradient);
}

.timerPaused {
  animation-play-state: paused;
}

/* Styleguide preview: drawn part-way down and held. */
.timerStill {
  animation-delay: calc(var(--toast-duration) * -0.38);
}

@keyframes toast-in {
  from {
    opacity: 0;
    translate: 0 calc(100% + 16px);
  }
}

@keyframes toast-out {
  to {
    opacity: 0;
    translate: 40px 0;
  }
}

@keyframes toast-timer {
  to {
    transform: scaleX(0);
  }
}

@keyframes toast-fade {
  from {
    opacity: 0;
  }
}

@keyframes toast-fade-out {
  to {
    opacity: 0;
  }
}

/* Reduced motion: toasts fade in and out in place, the stack re-lays out
   without travel, and the draining rule is dropped (the timer still runs
   and still pauses on hover or focus). */
@media (prefers-reduced-motion: reduce) {
  .list {
    transition: none;
  }

  .toast {
    transition:
      opacity 200ms linear,
      box-shadow var(--dur) var(--ease);
    animation: toast-fade 200ms linear both;
  }

  .leaving {
    animation: toast-fade-out 200ms linear forwards;
  }

  .timer {
    display: none;
  }
}

@media (max-width: 520px) {
  .region {
    right: 16px;
    bottom: 16px;
  }
}

"use client";

import {
  createContext,
  useCallback,
  useContext,
  useEffect,
  useLayoutEffect,
  useMemo,
  useRef,
  useState,
  type CSSProperties,
  type FocusEvent,
  type ReactNode,
} from "react";
import { cx } from "../_internal/cx";
import { Portal } from "../_internal/portal";
import { IconAlertCircle, IconCheckCircle, IconInfo, IconX } from "../Icon/Icon";
import { Spinner } from "../Spinner/Spinner";
import styles from "./Toast.module.css";

export type ToastTone = "success" | "error" | "info" | "loading";

export type ToastOptions = {
  description?: ReactNode;
  action?: { label: string; onClick: () => void };
  /** ms before auto-dismiss. Errors and loading toasts never auto-dismiss. */
  duration?: number;
};

type ToastItem = ToastOptions & { id: number; tone: ToastTone; title: ReactNode };

/** A toast in the stack. leaving = playing its exit before removal. */
type Entry = ToastItem & { leaving?: boolean };

export type ToastApi = {
  success: (title: ReactNode, options?: ToastOptions) => number;
  /** Stays until dismissed: the user must get to read what failed. */
  error: (title: ReactNode, options?: ToastOptions) => number;
  info: (title: ReactNode, options?: ToastOptions) => number;
  /** In flight. Returns an id to settle with update() or dismiss(). */
  loading: (title: ReactNode, options?: ToastOptions) => number;
  update: (id: number, patch: Partial<Omit<ToastItem, "id">>) => void;
  dismiss: (id: number) => void;
  /** Shows loading, then success or error when the promise settles. */
  promise: <T>(
    promise: Promise<T>,
    messages: { loading: ReactNode; success: ReactNode | ((value: T) => ReactNode); error: ReactNode | ((err: unknown) => ReactNode) },
  ) => Promise<T>;
};

const ToastContext = createContext<ToastApi | null>(null);

export function useToast(): ToastApi {
  const api = useContext(ToastContext);
  if (!api) throw new Error("useToast must be used inside <ToastProvider>.");
  return api;
}

const DEFAULT_DURATION = 5000;
/** Live toasts kept. The oldest leaves when a fifth arrives. */
const MAX_VISIBLE = 4;
/** Matches the exit animation in Toast.module.css. */
const EXIT_MS = 220;
/** Space between toasts when the stack is fanned out. */
const GAP = 10;
/** How far each toast behind the front one peeks out above it, collapsed. */
const PEEK = 9;
/** Toasts drawn behind the front one while collapsed; the rest wait hidden. */
const STACK_DEPTH = 2;

const isTimed = (t: ToastItem) => t.tone !== "error" && t.tone !== "loading";

/** Mount once, in the root layout. */
export function ToastProvider({ children }: { children: ReactNode }) {
  const [toasts, setToasts] = useState<Entry[]>([]);
  const nextId = useRef(1);
  const exitTimers = useRef(new Map<number, number>());

  // Dismissal plays the exit first; the effect below removes it afterwards.
  const dismiss = useCallback(
    (id: number) => setToasts((list) => list.map((t) => (t.id === id && !t.leaving ? { ...t, leaving: true } : t))),
    [],
  );

  const push = useCallback((tone: ToastTone, title: ReactNode, options?: ToastOptions) => {
    const id = nextId.current++;
    setToasts((list) => {
      const next: Entry[] = [...list, { id, tone, title, ...options }];
      const live = next.filter((t) => !t.leaving);
      const overflow = new Set(live.slice(0, Math.max(0, live.length - MAX_VISIBLE)).map((t) => t.id));
      return overflow.size ? next.map((t) => (overflow.has(t.id) ? { ...t, leaving: true } : t)) : next;
    });
    return id;
  }, []);

  const update = useCallback(
    (id: number, patch: Partial<Omit<ToastItem, "id">>) =>
      setToasts((list) => list.map((t) => (t.id === id ? { ...t, ...patch } : t))),
    [],
  );

  useEffect(() => {
    const timers = exitTimers.current;
    for (const t of toasts) {
      if (!t.leaving || timers.has(t.id)) continue;
      timers.set(
        t.id,
        window.setTimeout(() => {
          timers.delete(t.id);
          setToasts((list) => list.filter((x) => x.id !== t.id));
        }, EXIT_MS),
      );
    }
  }, [toasts]);

  useEffect(() => {
    const timers = exitTimers.current;
    return () => {
      for (const timer of timers.values()) window.clearTimeout(timer);
      timers.clear();
    };
  }, []);

  const api = useMemo<ToastApi>(
    () => ({
      success: (title, o) => push("success", title, o),
      error: (title, o) => push("error", title, o),
      info: (title, o) => push("info", title, o),
      loading: (title, o) => push("loading", title, o),
      update,
      dismiss,
      promise: async (promise, messages) => {
        const id = push("loading", messages.loading);
        try {
          const value = await promise;
          update(id, {
            tone: "success",
            title: typeof messages.success === "function" ? messages.success(value) : messages.success,
          });
          return value;
        } catch (err) {
          update(id, {
            tone: "error",
            title: typeof messages.error === "function" ? messages.error(err) : messages.error,
          });
          throw err;
        }
      },
    }),
    [push, update, dismiss],
  );

  return (
    <ToastContext.Provider value={api}>
      {children}
      <Portal>
        <section data-slot="toaster" className={styles.region} aria-label="Notifications">
          <ToastStack toasts={toasts} onDismiss={dismiss} live />
        </section>
      </Portal>
    </ToastContext.Provider>
  );
}

export type ToastPreviewItem = {
  /** Stable key: keep it when other items are removed. */
  id: number;
  tone: ToastTone;
  title: ReactNode;
  description?: ReactNode;
  action?: { label: string; onClick: () => void };
};

/**
 * The real stack, rendered in place with no timers and no live region, so a
 * styleguide can show it without anyone clicking. Newest last, as it would
 * arrive. `expanded` pins the stack fanned out; otherwise it collapses and
 * fans out on hover or focus exactly as the live one does.
 */
export function ToastStackPreview({
  items,
  expanded,
  onDismiss,
  className,
}: {
  items: ReadonlyArray<ToastPreviewItem>;
  expanded?: boolean;
  /** Receives the dismissed item's id. */
  onDismiss?: (id: number) => void;
  className?: string;
}) {
  const toasts = useMemo<Entry[]>(() => items.map((item) => ({ ...item })), [items]);
  return (
    <div data-slot="toast-stack-preview" className={cx(styles.preview, className)}>
      <ToastStack toasts={toasts} onDismiss={(id) => onDismiss?.(id)} expanded={expanded} still />
    </div>
  );
}

/**
 * Newest in front. Collapsed, the ones behind are clamped to the front
 * toast's height, stepped back and up so their edges show as a deck. Hover
 * or focus inside fans the stack out and pauses every timer.
 */
function ToastStack({
  toasts,
  onDismiss,
  live,
  expanded: pinned,
  still,
}: {
  toasts: Entry[];
  onDismiss: (id: number) => void;
  /** The live region. Off for previews so nothing is announced. */
  live?: boolean;
  expanded?: boolean;
  /** No timers: the timer bar is drawn part-way and held. */
  still?: boolean;
}) {
  const [heights, setHeights] = useState<Record<number, number>>({});
  const [hovered, setHovered] = useState(false);
  const [focused, setFocused] = useState(false);
  const expanded = pinned ?? (hovered || focused);

  const listRef = useRef<HTMLOListElement>(null);

  const onHeight = useCallback((id: number, h: number) => {
    setHeights((prev) => (prev[id] === h ? prev : { ...prev, [id]: h }));
  }, []);

  // Closing the toast that holds focus hands focus to the newest one left,
  // or lets it go (which collapses the stack) when it was the last. Without
  // this, focus dies with the removed node and the stack stays fanned out
  // with every timer paused.
  const dismissWithFocus = useCallback(
    (id: number) => {
      const list = listRef.current;
      if (list?.contains(document.activeElement)) {
        const rest = Array.from(list.querySelectorAll<HTMLElement>("li[data-toast-id]")).filter(
          (li) => li.dataset.toastId !== String(id) && !li.hasAttribute("aria-hidden"),
        );
        const next = rest[rest.length - 1]?.querySelector<HTMLElement>("button");
        if (next) next.focus();
        else (document.activeElement as HTMLElement | null)?.blur();
      }
      onDismiss(id);
    },
    [onDismiss],
  );

  // Newest first. Leaving toasts drop out of the layout at once, so the rest
  // close up while the leaver plays its exit from where it was.
  const front = toasts.filter((t) => !t.leaving).reverse();
  const layout = new Map<number, { index: number; offset: number }>();
  let offset = 0;
  front.forEach((t, index) => {
    layout.set(t.id, { index, offset });
    offset += (heights[t.id] ?? 0) + GAP;
  });
  const frontHeight = front[0] ? (heights[front[0].id] ?? 0) : 0;
  const stackHeight = expanded
    ? Math.max(0, offset - GAP)
    : frontHeight + Math.min(front.length - 1, STACK_DEPTH) * PEEK;

  const onBlur = (e: FocusEvent<HTMLOListElement>) => {
    if (!e.currentTarget.contains(e.relatedTarget as Node | null)) setFocused(false);
  };

  return (
    <ol data-slot="toast-stack"
      ref={listRef}
      className={cx(styles.list, expanded && styles.expanded)}
      style={{ height: toasts.length ? stackHeight : 0 }}
      aria-live={live ? "polite" : undefined}
      aria-relevant={live ? "additions text" : undefined}
      onMouseEnter={() => setHovered(true)}
      onMouseLeave={() => setHovered(false)}
      onFocus={() => setFocused(true)}
      onBlur={onBlur}
    >
      {toasts.map((t) => (
        <Toast
          key={t.id}
          item={t}
          place={layout.get(t.id)}
          frontHeight={frontHeight}
          ownHeight={heights[t.id]}
          expanded={expanded}
          paused={expanded}
          still={still}
          dismiss={dismissWithFocus}
          onHeight={onHeight}
        />
      ))}
    </ol>
  );
}

const ICON: Record<ToastTone, ReactNode> = {
  success: <IconCheckCircle size={17} />,
  error: <IconAlertCircle size={17} />,
  info: <IconInfo size={17} />,
  loading: <Spinner size={16} tone="current" />,
};

function Toast({
  item,
  place,
  frontHeight,
  ownHeight,
  expanded,
  paused,
  still,
  dismiss,
  onHeight,
}: {
  item: Entry;
  /** Undefined while leaving. */
  place?: { index: number; offset: number };
  frontHeight: number;
  /** Measured natural height; undefined until the first measure. */
  ownHeight?: number;
  expanded: boolean;
  paused: boolean;
  still?: boolean;
  dismiss: (id: number) => void;
  onHeight: (id: number, h: number) => void;
}) {
  const { id } = item;
  const timed = isTimed(item) && !still;
  const duration = item.duration ?? DEFAULT_DURATION;
  const bodyRef = useRef<HTMLDivElement>(null);
  const remaining = useRef(duration);

  // A leaving toast keeps the place it had, so it exits from where it sat.
  const [held, setHeld] = useState(place ?? { index: 0, offset: 0 });
  if (place && (place.index !== held.index || place.offset !== held.offset)) setHeld(place);
  const { index, offset } = place ?? held;

  // Report the natural height. Measured on the body, which is never clamped.
  useLayoutEffect(() => {
    const el = bodyRef.current;
    if (!el) return;
    onHeight(id, el.offsetHeight);
    const observer = new ResizeObserver(() => onHeight(id, el.offsetHeight));
    observer.observe(el);
    return () => observer.disconnect();
  }, [id, onHeight]);

  // A new tone (loading → success) or duration starts a fresh countdown.
  useEffect(() => {
    remaining.current = duration;
  }, [duration, item.tone]);

  // Counts down what is left, so hovering pauses rather than restarts: the
  // bar (paused by the same flag in CSS) and the timer stay in step.
  useEffect(() => {
    if (!timed || paused || item.leaving) return;
    const started = Date.now();
    const timer = window.setTimeout(() => dismiss(id), Math.max(0, remaining.current));
    return () => {
      window.clearTimeout(timer);
      remaining.current -= Date.now() - started;
    };
  }, [timed, paused, item.leaving, item.tone, duration, id, dismiss]);

  const behind = !expanded && index > 0;
  const vars = {
    "--index": index,
    "--offset": `${offset}px`,
    "--front-height": `${frontHeight}px`,
    "--own-height": ownHeight ? `${ownHeight}px` : "auto",
    "--toast-duration": `${duration}ms`,
  } as CSSProperties;

  return (
    <li data-slot="toast"
      className={cx(
        styles.toast,
        styles[item.tone],
        behind && styles.behind,
        behind && frontHeight > 0 && styles.clamped,
        !expanded && index > STACK_DEPTH && styles.hidden,
        item.leaving && styles.leaving,
      )}
      style={vars}
      role={item.tone === "error" ? "alert" : undefined}
      aria-busy={item.tone === "loading" || undefined}
      aria-hidden={item.leaving || undefined}
      data-toast-id={id}
    >
      <div ref={bodyRef} className={styles.body}>
        <span className={styles.icon} aria-hidden="true">
          {ICON[item.tone]}
        </span>
        <div className={styles.content}>
          <p className={styles.title}>{item.title}</p>
          {item.description ? <p className={styles.description}>{item.description}</p> : null}
          {item.action ? (
            <button
              type="button"
              className={styles.action}
              tabIndex={behind ? -1 : undefined}
              onClick={() => {
                item.action?.onClick();
                dismiss(id);
              }}
            >
              {item.action.label}
            </button>
          ) : null}
        </div>
        {item.tone !== "loading" ? (
          <button
            type="button"
            className={styles.close}
            tabIndex={behind ? -1 : undefined}
            onClick={() => dismiss(id)}
            aria-label="Dismiss notification"
          >
            <IconX size={14} />
          </button>
        ) : null}
      </div>
      {isTimed(item) ? (
        <span
          key={`${item.tone}-${duration}`}
          className={cx(styles.timer, (paused || still) && styles.timerPaused, still && styles.timerStill)}
          aria-hidden="true"
        />
      ) : null}
    </li>
  );
}
